 \\u0915\\u0940 \\u092a\\u094d\\u0930\\u093e\\u0915\\u0943\\u0924\\u093f\\u0915 \\u0906\\u0935\\u0927\\u093f\\u0915\\u0924\\u093e, \\u0909\\u092a-\\u0906\\u0935\\u0927\\u093f\\u0915\\u0924\\u093e, \\u092c\\u0939\\u0941-\\u0906\\u0935\\u0927\\u093f\\u0915 \\u0938\\u0902\\u092f\\u094b\\u091c\\u0928 \\u0914\\u0930 \\u092c\\u0947\\u092e\\u0947\\u0932 \\u0905\\u0935\\u0927\\u093f\\u092f\\u093e\\u0902\\u2014PDF (Periodicity-based / Periodic Decomposition Framework) \\u092e\\u0949\\u0921\\u0932 \\u0915\\u0947 \\u0926\\u0940\\u0930\\u094d\\u0918\\u0915\\u093e\\u0932\\u093f\\u0915 \\u092a\\u0942\\u0930\\u094d\\u0935\\u093e\\u0928\\u0941\\u092e\\u093e\\u0928 (Long-term Time Series Forecasting) \\u092a\\u094d\\u0930\\u0926\\u0930\\u094d\\u0936\\u0928 \\u0915\\u094b \\u0915\\u0948\\u0938\\u0947 \\u092a\\u094d\\u0930\\u092d\\u093e\\u0935\\u093f\\u0924 \\u0915\\u0930\\u0924\\u0940 \\u0939\\u0948\\u0902\\u0964\\n\\n### 1.2 \\u0938\\u0948\\u0926\\u094d\\u0927\\u093e\\u0902\\u0924\\u093f\\u0915 \\u0924\\u0930\\u094d\\u0915 (Rationale)\\n1. **\\u0921\\u0947\\u091f\\u093e\\u0938\\u0947\\u091f \\u0915\\u0940 \\u0906\\u0902\\u0924\\u0930\\u093f\\u0915 \\u0906\\u0935\\u0927\\u093f\\u0915\\u0924\\u093e (Intrinsic Periodicity of ETTm1):**\\n   ETTm1 \\u0921\\u0947\\u091f\\u093e\\u0938\\u0947\\u091f 15-\\u092e\\u093f\\u0928\\u091f \\u0915\\u0947 \\u0905\\u0902\\u0924\\u0930\\u093e\\u0932 \\u092a\\u0930 \\u0935\\u093f\\u0926\\u094d\\u092f\\u0941\\u0924 \\u091f\\u094d\\u0930\\u093e\\u0902\\u0938\\u092b\\u093e\\u0930\\u094d\\u092e\\u0930 \\u0915\\u0947 \\u0924\\u093e\\u092a\\u092e\\u093e\\u0928 \\u0914\\u0930 \\u0932\\u094b\\u0921 \\u0921\\u0947\\u091f\\u093e \\u0915\\u094b \\u0930\\u093f\\u0915\\u0949\\u0930\\u094d\\u0921 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0907\\u0938\\u0915\\u0947 \\u092d\\u094c\\u0924\\u093f\\u0915 \\u0938\\u0902\\u091a\\u093e\\u0932\\u0928 \\u092e\\u0947\\u0902 \\u0938\\u094d\\u092a\\u0937\\u094d\\u091f \\u091a\\u0915\\u094d\\u0930\\u0940\\u092f \\u092a\