od (FFT/Autocorrelation):** \\u0921\\u0947\\u091f\\u093e \\u0938\\u0947 \\u0938\\u094d\\u0935\\u0924\\u0903 \\u092a\\u0939\\u091a\\u093e\\u0928\\u0940 \\u0917\\u0908 \\u091f\\u0949\\u092a-k \\u0905\\u0935\\u0927\\u093f\\u092f\\u093e\\u0902\\u0964<br>2. **No-Period / Identity Baseline:** \\u092c\\u093f\\u0928\\u093e \\u092a\\u0940\\u0930\\u093f\\u092f\\u0921\\u093f\\u0915 \\u0921\\u0940\\u0915\\u0902\\u092a\\u094b\\u091c\\u093f\\u0936\\u0928 \\u092f\\u093e \\u0921\\u093f\\u092b\\u093c\\u0949\\u0932\\u094d\\u091f \\u0928\\u094d\\u092f\\u0942\\u091f\\u094d\\u0930\\u0932 \\u092a\\u0940\\u0930\\u093f\\u092f\\u0921\\u0964 | - \\u0915\\u094d\\u092f\\u093e \\u0939\\u0938\\u094d\\u0924\\u0928\\u093f\\u0930\\u094d\\u092e\\u093f\\u0924 (manual) \\u0921\\u094b\\u092e\\u0947\\u0928 \\u091c\\u094d\\u091e\\u093e\\u0928 \\u0911\\u091f\\u094b-\\u0921\\u093f\\u091f\\u0947\\u0915\\u094d\\u091f\\u0947\\u0921 \\u092a\\u0940\\u0930\\u093f\\u092f\\u0921 \\u0938\\u0947 \\u092c\\u0947\\u0939\\u0924\\u0930 \\u0939\\u0948?<br>- \\u0915\\u094d\\u092f\\u093e \\u092a\\u0940\\u0930\\u093f\\u092f\\u0921\\u093f\\u0915 \\u092e\\u0949\\u0921\\u094d\\u092f\\u0942\\u0932 \\u0915\\u094b \\u091c\\u094b\\u0921\\u093c\\u0928\\u0947 \\u0938\\u0947 \\u0938\\u093e\\u0902\\u0916\\u094d\\u092f\\u093f\\u0915\\u0940\\u092f \\u0938\\u0941\\u0927\\u093e\\u0930 \\u092e\\u093f\\u0932\\u0924\\u093e \\u0939\\u0948? |\\n\\n---\\n\\n## 3. \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u093f\\u0924 \\u091a\\u0930 \\u090f\\u0935\\u0902 \\u092a\\u094d\\u0930\\u092f\\u094b\\u0917\\u093e\\u0924\\u094d\\u092e\\u0915 \\u092a\\u094d\\u0930\\u094b\\u091f\\u094b\\u0915\\u0949\\u0932 (Controlled Variables & Setup)\\n\\n\\u092a\\u0942\\u0930\\u094d\\u0935\\u093e\\u0917\\u094d\\u0930\\u0939 (bias) \\u0938\\u0947 \\u092c\\u091a\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u092a\\u0940\\u0930\\u093f\\u092f\\u0921 \\u0915\\u0947 \\u0905\\u0924\\u093f\\u0930\\u093f\\u0915\\u094d\\u0924 \\u0905\\u0928\\u094d\\u092f \\u0938\\u0